BEGIN TRANSACTION;
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(20) NOT NULL, "phone" varchar(20) NULL, "company_name" varchar(100) NULL, "is_available" bool NOT NULL, "location" varchar(100) NULL, "fcm_token" text NULL, "kam_specialization" varchar(20) NULL, "avatar" varchar(255) NOT NULL);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_userdevice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fcm_token" text NOT NULL UNIQUE, "device_type" varchar(20) NOT NULL, "device_name" varchar(100) NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ai_core_aiexecution" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "purpose" varchar(50) NOT NULL, "provider" varchar(80) NOT NULL, "model_name" varchar(160) NOT NULL, "prompt_version" varchar(64) NOT NULL, "status" varchar(20) NOT NULL, "latency_ms" integer unsigned NULL CHECK ("latency_ms" >= 0), "input_tokens" integer unsigned NULL CHECK ("input_tokens" >= 0), "output_tokens" integer unsigned NULL CHECK ("output_tokens" >= 0), "error_code" varchar(80) NOT NULL, "created_at" datetime NOT NULL, "completed_at" datetime NULL, "conversation_id" bigint NOT NULL REFERENCES "ai_core_conversation" ("id") DEFERRABLE INITIALLY DEFERRED, "message_id" bigint NULL REFERENCES "ai_core_message" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ai_core_companyprofilesnapshot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "version" integer unsigned NOT NULL CHECK ("version" >= 0), "schema_version" varchar(20) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "content_hash" varchar(64) NOT NULL, "created_at" datetime NOT NULL, "conversation_id" bigint NOT NULL REFERENCES "ai_core_conversation" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_profile_snapshot_version" UNIQUE ("conversation_id", "version"));
CREATE TABLE "ai_core_conversation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(20) NOT NULL, "state_version" integer unsigned NOT NULL CHECK ("state_version" >= 0), "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "ai_core_message" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(16) NOT NULL, "content" text NOT NULL, "idempotency_key" varchar(100) NOT NULL, "status" varchar(20) NOT NULL, "attempt_count" smallint unsigned NOT NULL CHECK ("attempt_count" >= 0), "error_code" varchar(80) NOT NULL, "result_data" text NOT NULL CHECK ((JSON_VALID("result_data") OR "result_data" IS NULL)), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "conversation_id" bigint NOT NULL REFERENCES "ai_core_conversation" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_message_idempotency_key" UNIQUE ("conversation_id", "idempotency_key"));
CREATE TABLE "ai_core_recommendationrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "catalog_version" varchar(64) NOT NULL, "input_fingerprint" varchar(64) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "created_at" datetime NOT NULL, "conversation_id" bigint NOT NULL REFERENCES "ai_core_conversation" ("id") DEFERRABLE INITIALLY DEFERRED, "profile_snapshot_id" bigint NOT NULL REFERENCES "ai_core_companyprofilesnapshot" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_recommendation_fingerprint" UNIQUE ("profile_snapshot_id", "input_fingerprint"));
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "authtoken_token" ("key" varchar(40) NOT NULL PRIMARY KEY, "created" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "catalog_offerquestion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question_text" varchar(300) NOT NULL, "question_type" varchar(30) NOT NULL, "options" text NOT NULL CHECK ((JSON_VALID("options") OR "options" IS NULL)), "is_required" bool NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "help_text" varchar(255) NOT NULL, "scoring_weight" integer unsigned NOT NULL CHECK ("scoring_weight" >= 0), "questionnaire_id" bigint NOT NULL REFERENCES "catalog_offerquestionnaire" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "catalog_offerquestionnaire" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" text NOT NULL, "target_offer_name" varchar(150) NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "service_id" bigint NULL REFERENCES "catalog_servicecatalog" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "catalog_servicecatalog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "category" varchar(20) NOT NULL, "description" text NOT NULL, "benefits" text NOT NULL, "technical_requirements" text NOT NULL CHECK ((JSON_VALID("technical_requirements") OR "technical_requirements" IS NULL)));
