CREATE TABLE "sales_plaque_assigned_salespersons" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "plaque_id" bigint NOT NULL REFERENCES "sales_plaque" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_referrallead" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "referral_type" varchar(20) NOT NULL, "company_name" varchar(150) NOT NULL, "contact_person" varchar(100) NOT NULL, "phone" varchar(50) NOT NULL, "notes" text NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "field_report_id" bigint NOT NULL REFERENCES "sales_fieldintelligencereport" ("id") DEFERRABLE INITIALLY DEFERRED, "source_enterprise_id" bigint NOT NULL REFERENCES "sales_enterprise" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_salesincentivepoint" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action_type" varchar(30) NOT NULL, "description" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "field_report_id" bigint NULL REFERENCES "sales_fieldintelligencereport" ("id") DEFERRABLE INITIALLY DEFERRED, "salesperson_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "points" integer NOT NULL);
CREATE TABLE "sales_salesnotification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "message" text NOT NULL, "notification_type" varchar(50) NOT NULL, "payload" text NOT NULL CHECK ((JSON_VALID("payload") OR "payload" IS NULL)), "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "plaque_id" bigint NULL REFERENCES "sales_plaque" ("id") DEFERRABLE INITIALLY DEFERRED, "recipient_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_scrapercredential" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "platform" varchar(50) NOT NULL UNIQUE, "cookies_value" text NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "sales_segmentationconfig" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tpe_max_revenue" decimal NOT NULL, "pme_max_revenue" decimal NOT NULL, "backoffice_entity_label" varchar(100) NOT NULL, "kam_entity_label" varchar(100) NOT NULL, "updated_at" datetime NOT NULL, "updated_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_tradeaudit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "competitor_name" varchar(100) NOT NULL, "satisfaction_score" integer NOT NULL, "friction_reasons" text NOT NULL CHECK ((JSON_VALID("friction_reasons") OR "friction_reasons" IS NULL)), "monthly_spend_estimated" decimal NULL, "is_priority_friction_alert" bool NOT NULL, "alert_notes" text NOT NULL, "created_at" datetime NOT NULL, "enterprise_id" bigint NOT NULL REFERENCES "sales_enterprise" ("id") DEFERRABLE INITIALLY DEFERRED, "field_report_id" bigint NOT NULL REFERENCES "sales_fieldintelligencereport" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_visitformsubmission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "target_offer_name" varchar(150) NOT NULL, "answers" text NOT NULL CHECK ((JSON_VALID("answers") OR "answers" IS NULL)), "ai_summary" text NOT NULL, "qualification_score" integer unsigned NOT NULL CHECK ("qualification_score" >= 0), "detected_needs" text NOT NULL CHECK ((JSON_VALID("detected_needs") OR "detected_needs" IS NULL)), "objections_noted" text NOT NULL, "next_action" varchar(255) NOT NULL, "status" varchar(30) NOT NULL, "created_at" datetime NOT NULL, "enterprise_id" bigint NOT NULL REFERENCES "sales_enterprise" ("id") DEFERRABLE INITIALLY DEFERRED, "questionnaire_id" bigint NULL REFERENCES "catalog_offerquestionnaire" ("id") DEFERRABLE INITIALLY DEFERRED, "salesperson_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_visitpreparation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "hypothesis_to_verify" text NOT NULL, "custom_pitch" text NOT NULL, "key_questions" text NOT NULL, "meeting_objective" varchar(255) NOT NULL, "scheduled_date" datetime NULL, "created_at" datetime NOT NULL, "enterprise_id" bigint NOT NULL REFERENCES "sales_enterprise" ("id") DEFERRABLE INITIALLY DEFERRED, "salesperson_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sales_visitreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "raw_transcript" text NOT NULL, "executive_summary" text NOT NULL, "confirmed_needs" text NOT NULL CHECK ((JSON_VALID("confirmed_needs") OR "confirmed_needs" IS NULL)), "objections_raised" text NOT NULL CHECK ((JSON_VALID("objections_raised") OR "objections_raised" IS NULL)), "actions_todo" text NOT NULL CHECK ((JSON_VALID("actions_todo") OR "actions_todo" IS NULL)), "follow_up_email_draft" text NOT NULL, "audio_file_path" varchar(255) NULL, "created_at" datetime NOT NULL, "preparation_id" bigint NOT NULL UNIQUE REFERENCES "sales_visitpreparation" ("id") DEFERRABLE INITIALLY DEFERRED, "ai_feedback_comments" text NOT NULL, "ai_feedback_rating" integer NULL, "ai_feedback_sent_at" datetime NULL, "original_ai_output" text NOT NULL CHECK ((JSON_VALID("original_ai_output") OR "original_ai_output" IS NULL)));
CREATE TABLE "twin_businesstwin" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "current_state" text NOT NULL CHECK ((JSON_VALID("current_state") OR "current_state" IS NULL)), "proposed_state" text NOT NULL CHECK ((JSON_VALID("proposed_state") OR "proposed_state" IS NULL)), "recommended_services" text NOT NULL CHECK ((JSON_VALID("recommended_services") OR "recommended_services" IS NULL)), "roadmap" text NOT NULL CHECK ((JSON_VALID("roadmap") OR "roadmap" IS NULL)), "created_at" datetime NOT NULL, "prospect_dossier_id" bigint NOT NULL UNIQUE REFERENCES "kam_prospectdossier" ("id") DEFERRABLE INITIALLY DEFERRED);
